#include <queue>
#include <iostream>

int main() {
    std::queue<int> q;

    // Correct usage: Check first
    if (!q.empty()) {
        q.pop();
    } else {
        std::cerr << "Queue is empty, safe exit.\n";
    }

    // Incorrect usage (leads to UB if q is empty)
    // q.front();
    // q.pop();

    q.push(1);
    std::cout << q.front() << std::endl; // Safe, q is not empty
}
